INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 1, "カリン", -416.5, 190801, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 3.414, 1, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1000001, 62, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 1, "カリン", -416.5, 190801, "ミッションをクリアして、\n報酬をゲットしましょう！", 3.099, 2, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1000002, 62, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 1, "カリン", -416.5, 190801, "受け取ることができる\n報酬があるようです\n確認してみてください", 2.801, 3, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1000003, 63, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 1, "カリン", -416.5, 190801, "報酬がもらえますよ！\nチェックしてみてください", 0.0, 4, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1000004, 63, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 1, "カリン", -363.0, 190801, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2.12, 5, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1000005, 64, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 1, "カリン", -363.0, 190801, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1.68, 6, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1000006, 64, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 1, "カリン", -363.0, 190801, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2.33, 7, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1000007, 64, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3, 10201, "ラビリスタ", -285.0, 133701, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 5.18, 101, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1020101, 61, -6.0, 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10201, "クリスティーナ", -285.0, 133901, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 8.77, 201, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1020102, 61, -2.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6, 10201, "ネネカ", -285.0, 133801, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 15.5, 301, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1020103, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 10202, "ランファ", -285.0, 134301, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 9.061, 101, "2030/01/01 14:59:59", "2025/02/28 12:00:00", 1020201, 61, 0.0, 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10202, "チカ", -285.0, 134401, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 7.699, 201, "2030/01/01 14:59:59", "2025/02/28 12:00:00", 1020202, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10203, "アオイ", -285.0, 134601, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 8.595, 101, "2030/01/01 14:59:59", "2025/03/31 12:00:00", 1020301, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10203, "クローチェ", -285.0, 134501, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 7.758, 201, "2030/01/01 14:59:59", "2025/03/31 12:00:00", 1020302, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 10204, "ルイズマリー", -285.0, 132302, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 7.0, 101, "2030/01/01 14:59:59", "2025/04/30 12:00:00", 1020401, 61, 0.0, 6);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10204, "イロハ", -285.0, 132402, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 7.904, 201, "2030/01/01 14:59:59", "2025/04/30 12:00:00", 1020402, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10204, "ソノ", -285.0, 132502, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 8.487, 301, "2030/01/01 14:59:59", "2025/04/30 12:00:00", 1020403, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10205, "カノン", -285.0, 134901, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 8.763, 101, "2030/01/01 14:59:59", "2025/05/31 12:00:00", 1020502, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10205, "ツムギ", -285.0, 134801, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 6.417, 201, "2030/01/01 14:59:59", "2025/05/31 12:00:00", 1020503, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3, 10206, "エリス", -285.0, 135001, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 10.335, 101, "2030/01/01 14:59:59", "2025/06/30 12:00:00", 1020601, 61, 0.0, 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 10206, "シェフィ", -285.0, 135101, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 6.281, 201, "2030/01/01 14:59:59", "2025/06/30 12:00:00", 1020602, 61, 0.0, 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10206, "プレシア", -285.0, 135201, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 12.244, 301, "2030/01/01 14:59:59", "2025/06/30 12:00:00", 1020603, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 10207, "クリア", -285.0, 135301, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 6.339, 101, "2030/01/01 14:59:59", "2025/07/31 12:00:00", 1020701, 61, 0.0, 8);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7, 10207, "アネモネ", -285.0, 135401, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 8.184, 201, "2030/01/01 14:59:59", "2025/07/31 12:00:00", 1020702, 61, 0.0, 9);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (9, 10208, "アイラ", -285.0, 129101, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 3.906, 101, "2030/01/01 14:59:59", "2025/08/31 12:00:00", 1020801, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10208, "シナツ", -285.0, 129201, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 14.465, 201, "2030/01/01 14:59:59", "2025/08/31 12:00:00", 1020802, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10208, "ヒヨリ", -285.0, 100101, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 8.662, 301, "2030/01/01 14:59:59", "2025/08/31 12:00:00", 1020803, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10208, "レイ", -285.0, 100301, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 10.915, 401, "2030/01/01 14:59:59", "2025/08/31 12:00:00", 1020804, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10209, "ユキノ", -285.0, 135802, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 6.042, 101, "2030/01/01 14:59:59", "2025/09/30 12:00:00", 1020901, 61, 0.0, 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10209, "サツキ", -285.0, 135903, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 9.402, 201, "2030/01/01 14:59:59", "2025/09/30 12:00:00", 1020902, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8, 10209, "ルルィ", -285.0, 136902, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 8.16, 301, "2030/01/01 14:59:59", "2025/09/30 12:00:00", 1020903, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3, 10210, "カスミ", -285.0, 137401, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 5.0, 101, "2030/01/01 14:59:59", "2025/10/31 12:00:00", 1021001, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10210, "アラクネ", -285.0, 136001, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 8.12, 201, "2030/01/01 14:59:59", "2025/10/31 12:00:00", 1021002, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10210, "ナーナ", -285.0, 136202, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 6.386, 301, "2030/01/01 14:59:59", "2025/10/31 12:00:00", 1021003, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3, 10211, "ユイ", -285.0, 136402, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 7.438, 101, "2030/01/01 14:59:59", "2025/11/30 12:00:00", 1021101, 61, 0.0, 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10211, "ミソラ", -285.0, 136302, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 8.35, 201, "2030/01/01 14:59:59", "2025/11/30 12:00:00", 1021102, 61, 0.0, 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10212, "シズル", -285.0, 136501, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 5.0, 101, "2030/01/01 14:59:59", "2025/12/31 12:00:00", 1021201, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10212, "リノ", -285.0, 137902, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 5.25, 201, "2030/01/01 14:59:59", "2025/12/31 12:00:00", 1021202, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10212, "ラビリスタ", -285.0, 106801, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 7.5, 301, "2030/01/01 14:59:59", "2025/12/31 12:00:00", 1021203, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10213, "ライラエル", -285.0, 126501, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 8.204, 101, "2030/01/01 14:59:59", "2026/01/31 12:00:00", 1021301, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10213, "ネフィ＝ネラ", -285.0, 129701, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 7.176, 201, "2030/01/01 14:59:59", "2026/01/31 12:00:00", 1021302, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10213, "ヴァイオレット", -285.0, 133101, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 8.602, 301, "2030/01/01 14:59:59", "2026/01/31 12:00:00", 1021303, 61, 0.0, 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10213, "ライラエル", -285.0, 138101, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 10.14, 102, "2030/01/01 14:59:59", "2026/02/06 12:00:00", 1021304, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10213, "ネフィ＝ネラ", -285.0, 138201, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 10.152, 202, "2030/01/01 14:59:59", "2026/02/06 12:00:00", 1021305, 61, 0.0, 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10213, "ヴァイオレット", -285.0, 138001, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 9.688, 302, "2030/01/01 14:59:59", "2026/02/06 12:00:00", 1021306, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 10213, "ペコリーヌ", -285.0, 138301, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 5.928, 401, "2030/01/01 14:59:59", "2026/02/12 12:00:00", 1021307, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10214, "ワカナ", -285.0, 138702, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 9.19, 101, "2030/01/01 14:59:59", "2026/02/28 12:00:00", 1021401, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10214, "シオリ", -285.0, 138802, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 8.724, 201, "2030/01/01 14:59:59", "2026/02/28 12:00:00", 1021402, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10215, "グレイス", -285.0, 138902, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 7.758, 101, "2030/01/01 14:59:59", "2026/03/31 12:00:00", 1021501, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6, 10215, "キョウカ", -285.0, 139002, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 6.375, 201, "2030/01/01 14:59:59", "2026/03/31 12:00:00", 1021502, 61, 0.0, 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6, 10215, "ルルィ", -285.0, 136902, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 6.173, 301, "2030/01/01 14:59:59", "2026/03/31 12:00:00", 1021503, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6, 10216, "ミホ", -285.0, 139202, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 4.202, 101, "2030/01/01 14:59:59", "2026/04/30 12:00:00", 1021601, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6, 10216, "マホ", -285.0, 139302, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 2.842, 201, "2030/01/01 14:59:59", "2026/04/30 12:00:00", 1021602, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10216, "エリカ", -285.0, 139402, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 4.598, 301, "2030/01/01 14:59:59", "2026/04/30 12:00:00", 1021603, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10217, "リリ", -285.0, 125802, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 6.533, 101, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 1021701, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3, 10217, "プレシア", -285.0, 126102, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 5.0, 301, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 1021702, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3, 10217, "クリア", -285.0, 126002, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 5.214, 201, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 1021703, 61, 0.0, 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10217, "リリ", -285.0, 139501, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 8.781, 102, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 1021704, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 10217, "クリア", -285.0, 139601, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 6.529, 202, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 1021705, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3, 10217, "プレシア", -285.0, 139701, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 3.195, 302, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 1021706, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 10218, "ルイズマリー", -285.0, 139902, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 12.43, 101, "2030/01/01 14:59:59", "2026/06/30 12:00:00", 1021801, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 10218, "クレジッタ", -285.0, 140001, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 6.35, 201, "2030/01/01 14:59:59", "2026/06/30 12:00:00", 1021802, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10219, "フブキ", -285.0, 140102, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 10.23, 101, "2030/01/01 14:59:59", "2026/07/31 12:00:00", 1021901, 61, 0.0, 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10219, "ヴァンピィ", -285.0, 140201, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 5.584, 201, "2030/01/01 14:59:59", "2026/07/31 12:00:00", 1021902, 61, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6, 10220, "クローチェ", -285.0, 126401, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 2.8, 201, "2030/01/01 14:59:59", "2026/08/31 12:00:00", 1022001, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10220, "ヴルム", -285.0, 127802, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 8.9, 101, "2030/01/01 14:59:59", "2026/08/31 12:00:00", 1022002, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 10220, "クローチェ", -285.0, 140602, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 4.49, 202, "2030/01/01 14:59:59", "2026/08/31 12:00:00", 1022003, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 10220, "ヴルム", -285.0, 140501, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 9.42, 102, "2030/01/01 14:59:59", "2026/08/31 12:00:00", 1022004, 61, 0.0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 10220, "リーザ", -285.0, 140402, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 7.0, 301, "2030/01/01 14:59:59", "2026/08/31 12:00:00", 1022005, 61, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 2, "カリン", -416.5, 190805, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 3.414, 1, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 2000001, 62, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 2, "カリン", -416.5, 190805, "ミッションをクリアして、\n報酬をゲットしましょう！", 3.099, 2, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 2000002, 62, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 2, "カリン", -416.5, 190805, "受け取ることができる\n報酬があるようです\n確認してみてください", 2.801, 3, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 2000003, 63, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 2, "カリン", -416.5, 190805, "報酬がもらえますよ！\nチェックしてみてください", 0.0, 4, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 2000004, 63, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 2, "カリン", -363.0, 190805, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2.12, 5, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 2000005, 64, 0.0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 2, "カリン", -363.0, 190805, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1.68, 6, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 2000006, 64, 0.0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 2, "カリン", -363.0, 190805, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2.33, 7, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 2000007, 64, 0.0, 1);
